delete from public.together_schedule_templates where character_version_id::text like '25000000-0000-4000-8011-%';
insert into public.together_schedule_templates(
  character_version_id,day_of_week,start_minute,end_minute,location_id,activity,availability,
  energy_delta,mood_influence,variation_weight,metadata
)
select (item->>'character_version_id')::uuid,(item->>'day_of_week')::int,(item->>'start_minute')::int,
  (item->>'end_minute')::int,location.id,item->>'activity',item->>'availability',(item->>'energy_delta')::int,
  item->>'mood_influence',coalesce((item->>'variation_weight')::numeric,1),item->'metadata'
from northvale_schedule_payload cross join lateral jsonb_array_elements(data) item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000011'::uuid and location.slug=item->>'location_slug'
on conflict(character_version_id,day_of_week,start_minute) do update set end_minute=excluded.end_minute,
  location_id=excluded.location_id,activity=excluded.activity,availability=excluded.availability,
  energy_delta=excluded.energy_delta,mood_influence=excluded.mood_influence,
  variation_weight=excluded.variation_weight,metadata=excluded.metadata;

delete from public.together_character_schedule_events event using public.together_character_instances instance
where event.character_instance_id=instance.id and instance.character_version_id::text like '25000000-0000-4000-8011-%'
  and event.source in('generated','recurring') and event.starts_at>=date_trunc('day',now());

create temporary table northvale_social_payload(data jsonb) on commit drop;
insert into northvale_social_payload values($northvale_social$[{"source":"mara-ellison","target":"celeste-park","relationship_type":"childhood_friends","affinity":84,"trust":79,"history":"Mara and Celeste grew up in the same public-school class. Mara stayed in Old Vale while Celeste learned the resort from the inside, and their friendship survives recurring arguments about what compromise costs."},{"source":"mara-ellison","target":"eli-navarro","relationship_type":"unresolved_history","affinity":78,"trust":82,"history":"Mara and Eli almost left NorthVale together in their early twenties. Neither treats the past as a claim, but both remember the plan differently."},{"source":"mara-ellison","target":"malcolm-price","relationship_type":"civic_allies","affinity":76,"trust":86,"history":"Mara gives Malcolm a table before public meetings; Malcolm tells her which rumors are already becoming policy problems."},{"source":"leila-haddad","target":"caleb-morgan","relationship_type":"emergency_colleagues","affinity":79,"trust":91,"history":"Leila and Caleb have managed enough difficult transfers together to communicate in half-sentences when weather closes the road."},{"source":"leila-haddad","target":"elena-petrova","relationship_type":"recovery_colleagues","affinity":80,"trust":85,"history":"Leila handles medical limits while Elena helps people live inside them. They disagree carefully about when encouragement becomes pressure."},{"source":"sofia-reyes","target":"marcus-chen","relationship_type":"creative_collaborators","affinity":87,"trust":81,"history":"Sofia programs films and Marcus photographs the town. Their joint projects are admired partly because each is willing to reject the other’s most beautiful bad idea."},{"source":"sofia-reyes","target":"june-nakashima","relationship_type":"history_friends","affinity":82,"trust":88,"history":"Sofia and June trade public-history research, family photographs, and arguments about whether preserving an object is the same as preserving its meaning."},{"source":"june-nakashima","target":"graham-pike","relationship_type":"research_colleagues","affinity":78,"trust":90,"history":"June supplies archival discipline; Graham supplies decades of local reporting and refuses to let familiarity substitute for evidence."},{"source":"june-nakashima","target":"avery-callahan","relationship_type":"guarded_family_history","affinity":65,"trust":58,"history":"June believes Avery deserves to see the White Sunday page before publication. Avery worries the archive is about to turn her family into a lesson."},{"source":"tessa-ward","target":"aisha-grant","relationship_type":"close_friends","affinity":91,"trust":89,"history":"Tessa and Aisha met during an employee-shuttle delay and became each other’s most reliable source of practical advice and harmless bad ideas."},{"source":"tessa-ward","target":"nadine-baptiste","relationship_type":"younger_circle_friends","affinity":83,"trust":81,"history":"Tessa and Nadine trade books, lake walks, and honest conversations about being treated as younger than the decisions they are already making."},{"source":"eli-navarro","target":"amara-okoye","relationship_type":"culinary_rivals","affinity":73,"trust":77,"history":"Eli and Amara compete over staff meal, sourcing, and which dining room understands winter appetite better. They refer serious workers to each other without mentioning it."},{"source":"eli-navarro","target":"graham-pike","relationship_type":"after_hours_friends","affinity":81,"trust":86,"history":"Eli feeds Graham after talks; Graham edits the historical claims on Eli’s seasonal menus. Their arguments usually end with another plate."},{"source":"malcolm-price","target":"talia-valdez","relationship_type":"policy_allies","affinity":78,"trust":83,"history":"Malcolm and Talia agree that consultation must have authority, then challenge each other when law and lived consequences stop aligning neatly."},{"source":"celeste-park","target":"andre-baptiste","relationship_type":"operational_trust","affinity":76,"trust":92,"history":"Celeste and Andre can move guests, staff, and supplies through a storm without performing panic. Their trust was earned during a three-day highway closure."},{"source":"celeste-park","target":"imani-brooks","relationship_type":"professional_tension","affinity":64,"trust":75,"history":"Celeste needs opening decisions early; Imani refuses certainty the snow cannot support. Both respect the other enough to argue directly."},{"source":"amara-okoye","target":"marisol-vega","relationship_type":"hospitality_friends","affinity":86,"trust":87,"history":"Amara and Marisol protect one monthly meal from guests, vendors, and management conversations, then inevitably solve one staffing problem anyway."},{"source":"elena-petrova","target":"samir-patel","relationship_type":"recovery_colleagues","affinity":84,"trust":88,"history":"Elena and Samir share patients and a belief that recovery should return people to a life, not merely a sport."},{"source":"priya-desai","target":"theo-marchand","relationship_type":"hospitality_allies","affinity":80,"trust":83,"history":"Priya handles what guests ask for; Theo notices what they are actually trying to create. They protect staff from promises neither department can safely keep."},{"source":"gabriela-flores","target":"signe-dahl","relationship_type":"maker_mentorship","affinity":85,"trust":88,"history":"Signe taught Gabi to treat every repair note as engineering evidence rather than a favor somebody did for a teenager."},{"source":"gabriela-flores","target":"mila-novak","relationship_type":"technical_friends","affinity":82,"trust":79,"history":"Gabi and Mila trade tool access and argue about whether beautiful repair work should remain visible."},{"source":"riley-hart","target":"owen-kearney","relationship_type":"bandmates","affinity":90,"trust":87,"history":"Riley fronts the songs and Owen builds the arrangements. They can read a crowd together and still misread each other after rehearsal."},{"source":"riley-hart","target":"mateo-silva","relationship_type":"exes","affinity":70,"trust":76,"history":"Riley and Mateo ended a bright, brief first-season relationship without betrayal. Attraction survives; neither treats nostalgia as a reason to restart it."},{"source":"sabine-diarra","target":"anika-vogel","relationship_type":"climbing_partners","affinity":86,"trust":93,"history":"Sabine and Anika have shared enough difficult anchors to trust each other’s judgment while remaining competitive about route choice."},{"source":"valeria-cruz","target":"nico-alvarez","relationship_type":"friendly_exes","affinity":77,"trust":80,"history":"Valeria and Nico dated before their schedules became incompatible. They still dance, argue about music, and decline to turn familiarity into ownership."},{"source":"signe-dahl","target":"mila-novak","relationship_type":"technical_trust","affinity":79,"trust":91,"history":"Signe handles public equipment; Mila handles lift systems. Each knows exactly when the other’s “interesting” means stop using the machine."},{"source":"aisha-grant","target":"liam-oconnell","relationship_type":"first_season_friends","affinity":88,"trust":82,"history":"Aisha and Liam arrived the same week, learned the shuttle map together, and promised to tell each other when a bad day was becoming a bad decision."},{"source":"avery-callahan","target":"caleb-morgan","relationship_type":"exes","affinity":69,"trust":84,"history":"Avery and Caleb ended a serious relationship because emergency work consumed every shared plan. They remain the first person each calls when mountain judgment matters."},{"source":"avery-callahan","target":"imani-brooks","relationship_type":"safety_colleagues","affinity":81,"trust":94,"history":"Avery translates field conditions into patrol decisions; Imani supplies the forecast uncertainty Avery refuses to hide from crews."},{"source":"lucia-serrano","target":"liam-oconnell","relationship_type":"instructor_rivals","affinity":76,"trust":78,"history":"Lucía and Liam compete for return clients and teaching games, but each steps in immediately when the other’s group needs help."},{"source":"mika-tanaka","target":"sana-rahman","relationship_type":"mentor_trust","affinity":84,"trust":90,"history":"Sana is one of the few adults Mika trusts not to turn recovery into a moral test. Mika gives Sana unusually honest pain reports in return."},{"source":"mila-novak","target":"andre-baptiste","relationship_type":"infrastructure_tension","affinity":63,"trust":82,"history":"Andre needs reliable operations; Mila needs time to inspect what reliability is hiding. Their disagreements are blunt because neither can afford politeness that delays a decision."},{"source":"andre-baptiste","target":"nadine-baptiste","relationship_type":"siblings","affinity":92,"trust":94,"history":"Andre and Nadine are siblings who love each other without pretending the age gap has not made him overprotective and her allergic to being managed."},{"source":"rowan-lee","target":"samir-patel","relationship_type":"close_friends","affinity":88,"trust":91,"history":"Rowan and Samir became close through long trail conversations and a shared preference for useful care over inspirational speeches."},{"source":"maribel-morales","target":"evan-cho","relationship_type":"close_friends","affinity":89,"trust":90,"history":"Maribel and Evan share early trail reports, family meals, and the right to tell each other when work has swallowed the rest of the week."},{"source":"ingrid-solberg","target":"talia-valdez","relationship_type":"research_colleagues","affinity":82,"trust":86,"history":"Ingrid brings wildlife and watershed data; Talia insists the data be translated into authority rather than decorative consultation."},{"source":"dalia-farouk","target":"marisol-vega","relationship_type":"spa_peers","affinity":83,"trust":85,"history":"Dalia and Marisol exchange staffing advice and argue warmly about whether recovery spaces should feel social or protective."},{"source":"anika-vogel","target":"yusuf-demir","relationship_type":"guide_rivals","affinity":75,"trust":89,"history":"Anika and Yusuf choose different lines and teach different styles, but each trusts the other’s turnaround call without question."},{"source":"cassidy-reed","target":"graham-pike","relationship_type":"mentor_secret","affinity":86,"trust":79,"history":"Graham taught Cassidy to read old mechanical drawings. Cassidy does not know he created an education fund for her after her father’s death."},{"source":"tomas-ibarra","target":"marisol-vega","relationship_type":"old_friends","affinity":87,"trust":90,"history":"Tomás and Marisol grew up in neighboring households, survived each other’s worst teenage decisions, and now trade transport and hospitality favors without keeping score."},{"source":"yusuf-demir","target":"imani-brooks","relationship_type":"education_colleagues","affinity":80,"trust":92,"history":"Yusuf turns forecast uncertainty into field education; Imani corrects him whenever a memorable explanation becomes too certain."}]$northvale_social$::jsonb);
with authored as(
  select item->>'source' source_slug,item->>'target' target_slug,item->>'relationship_type' relationship_type,
    (item->>'affinity')::int affinity,(item->>'trust')::int trust,item->>'history' history
  from northvale_social_payload cross join lateral jsonb_array_elements(data) item
),directed as(
  select * from authored union all select target_slug,source_slug,relationship_type,affinity,trust,history from authored
)
insert into public.together_character_relationship_edges(
  world_id,source_template_id,target_template_id,relationship_type,affinity,trust,history,metadata
)
select '10000000-0000-4000-8000-000000000011'::uuid,source.id,target.id,edge.relationship_type,edge.affinity,edge.trust,edge.history,
  jsonb_build_object('source','northvale_social_graph_v1','memorySharing','event_only','authored',true,'knowledgeScope','relationship_and_district')
from directed edge join public.together_character_templates source on source.slug=edge.source_slug
join public.together_character_templates target on target.slug=edge.target_slug
on conflict(world_id,source_template_id,target_template_id) do update set relationship_type=excluded.relationship_type,
  affinity=excluded.affinity,trust=excluded.trust,history=excluded.history,metadata=excluded.metadata,updated_at=now();

create temporary table northvale_event_payload(data jsonb) on commit drop;
insert into northvale_event_payload values($northvale_events$[{"slug":"northvale-first-chair-breakfast","name":"First-Chair Breakfast","event_type":"social","location_slug":"gondola-commons","participant_slugs":["avery-callahan","imani-brooks","lucia-serrano","mika-tanaka","caleb-morgan","liam-oconnell","andre-baptiste","celeste-park"],"probability":0.82,"duration_minutes":150,"category":"community","tone":"bright","narrative_summary":"On Saturday opening mornings, mountain crews and early regulars gather for breakfast while patrol waits to ring the first-chair bell.","recurrence":{"frequency":"weekly","weekday":6,"startMinute":375}},{"slug":"northvale-drift-friday-sessions","name":"Friday Drift Sessions","event_type":"social","location_slug":"the-drift","participant_slugs":["riley-hart","owen-kearney","valeria-cruz","aisha-grant","mateo-silva","signe-dahl","gabriela-flores"],"probability":0.78,"duration_minutes":240,"category":"music","tone":"exciting","narrative_summary":"Riley and Owen anchor a loose Friday music night where worker circles, athletes, and artists overlap after shift.","recurrence":{"frequency":"weekly","weekday":5,"startMinute":1290}},{"slug":"northvale-lantern-square-winter-market","name":"Lantern Square Winter Market","event_type":"world","location_slug":"lantern-square","participant_slugs":["mara-ellison","june-nakashima","sofia-reyes","tessa-ward","eli-navarro","malcolm-price","gabriela-flores"],"probability":0.88,"duration_minutes":240,"category":"world","tone":"positive","narrative_summary":"Saturday market stalls bring food, repair tables, books, public notices, and the week’s least private conversations into Lantern Square.","recurrence":{"frequency":"weekly","weekday":6,"startMinute":540}},{"slug":"northvale-pine-lake-lantern-skate","name":"Pine Lake Lantern Skate","event_type":"social","location_slug":"pine-lake","participant_slugs":["rowan-lee","maribel-morales","ingrid-solberg","dalia-farouk","nadine-baptiste","evan-cho","samir-patel"],"probability":0.7,"duration_minutes":210,"category":"community","tone":"romantic","narrative_summary":"On calm Sunday afternoons, a maintained lake loop, sauna reservations, and the Lakehouse fire bring Pine Lake residents together before dark.","recurrence":{"frequency":"weekly","weekday":0,"startMinute":930}},{"slug":"northvale-silver-basin-guide-night","name":"Silver Basin Guide Night","event_type":"social","location_slug":"last-light-roadhouse","participant_slugs":["talia-valdez","anika-vogel","marisol-vega","cassidy-reed","tomas-ibarra","yusuf-demir","graham-pike","imani-brooks"],"probability":0.52,"duration_minutes":210,"category":"community","tone":"grounded","narrative_summary":"The first Monday basin table combines road conditions, field observations, food, old stories, and arguments that remain practical because everyone has work tomorrow.","recurrence":{"frequency":"monthly","ordinal":1,"weekday":1,"startMinute":1080}},{"slug":"northvale-storm-hold-at-the-alpine-room","name":"Storm Hold at The Alpine Room","event_type":"weather","location_slug":"alpine-room","participant_slugs":["celeste-park","amara-okoye","elena-petrova","priya-desai","theo-marchand","marcus-chen","leila-haddad"],"probability":0.3,"duration_minutes":180,"category":"weather","tone":"intimate","narrative_summary":"A high-wind lift hold and road delay fill The Alpine Room with stranded guests, off-shift staff, and conversations nobody scheduled.","recurrence":{"frequency":"weather_condition","weather":["heavy_snow","high_wind","road_closure"],"startRange":[900,1260]}}]$northvale_events$::jsonb);
insert into public.together_event_templates(
  id,name,event_type,world_id,default_location_id,participant_template_ids,significance,probability,
  duration_minutes,narrative_summary,state_effects,user_visibility,proactive_eligible,metadata,active,
  category,tone,scale,content_level,conditions,followups
)
select ('3b000000-0000-4000-8011-'||lpad(ordinality::text,12,'0'))::uuid,item->>'name',item->>'event_type',
  '10000000-0000-4000-8000-000000000011'::uuid,location.id,array(select template.id from public.together_character_templates template
    where template.slug=any(array(select jsonb_array_elements_text(item->'participant_slugs')))),
  .58,(item->>'probability')::numeric,(item->>'duration_minutes')::int,item->>'narrative_summary','{}'::jsonb,
  'contextual',true,jsonb_build_object('worldSlug','northvale','worldEvent',true,'recurrence',item->'recurrence','scheduleAware',true),
  true,
  case item->>'category' when 'community' then 'social' when 'music' then 'social' else item->>'category' end,
  case item->>'tone' when 'bright' then 'positive' when 'grounded' then 'positive' when 'intimate' then 'romantic' else item->>'tone' end,
  'normal','standard',jsonb_build_object('recurrence',item->'recurrence'),'{}'::text[]
from northvale_event_payload cross join lateral jsonb_array_elements(data) with ordinality payload(item,ordinality)
join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000011'::uuid and location.slug=item->>'location_slug'
on conflict(id) do update set name=excluded.name,event_type=excluded.event_type,default_location_id=excluded.default_location_id,
  participant_template_ids=excluded.participant_template_ids,probability=excluded.probability,duration_minutes=excluded.duration_minutes,
  narrative_summary=excluded.narrative_summary,metadata=excluded.metadata,conditions=excluded.conditions,active=true,updated_at=now();

create temporary table northvale_story_payload(data jsonb) on commit drop;
insert into northvale_story_payload values($northvale_stories$[{"slug":"northvale-white-sunday-log","title":"The White Sunday Log","category":"discovery","min_relationship_stage":"acquaintance","lead_slugs":["june-nakashima","avery-callahan","graham-pike"],"location_slugs":["miners-hall","ski-patrol-headquarters","argent-mine","last-light-roadhouse"],"premise":"A missing page from the 1912 White Sunday rescue log returns with names and decisions omitted from NorthVale’s official memory.","chapters":[{"title":"The returned page","narrative_seed":"June shows the player a water-damaged rescue-log page delivered without provenance to Miners Hall."},{"title":"The slide path","narrative_seed":"Avery compares the old account with modern terrain knowledge and recognizes a decision her family still tells differently."},{"title":"The handwriting","narrative_seed":"Graham identifies the writer and explains why the later public account may have protected survivors rather than simply deceived them."},{"title":"A living correction","narrative_seed":"At Last Light, the group decides how to document the truth without turning grief, rescue labor, or living families into a spectacle."}]},{"slug":"northvale-silver-basin-line","title":"The Silver Basin Line","category":"community","min_relationship_stage":"friend","lead_slugs":["talia-valdez","imani-brooks","malcolm-price","celeste-park","ingrid-solberg"],"location_slugs":["avalanche-forecast-center","miners-hall","high-country-guides","silver-basin"],"premise":"A proposed controlled-access line into Silver Basin forces real questions about water, rescue burden, employment, public access, wildlife, and Accord obligations.","chapters":[{"title":"The map nobody saw","narrative_seed":"Talia notices that the public concept map omits a watershed protection corridor included in the consultation draft."},{"title":"Conditions, not slogans","narrative_seed":"Imani and Ingrid explain how snow loading and habitat concerns change seasonally rather than supplying one permanent answer."},{"title":"The buried obligation","narrative_seed":"Malcolm finds an Accord clause linking any new terrain to rescue funding and worker transport, complicating both support and opposition."},{"title":"The line in public","narrative_seed":"Celeste joins a bounded public session where the player helps keep the argument specific enough for an honest decision to remain possible."}]},{"slug":"northvale-one-more-winter","title":"One More Winter","category":"relationship","min_relationship_stage":"acquaintance","lead_slugs":["riley-hart","owen-kearney","aisha-grant","mateo-silva"],"location_slugs":["juniper-house","driftline-laundry","the-drift","lantern-square"],"premise":"The possible sale of Juniper House turns a worker residence, band rehearsal space, friendship network, and collection of temporary lives into a choice about permanence.","chapters":[{"title":"The notice","narrative_seed":"Aisha finds a lease notice that says less than the rumor spreading through Juniper House."},{"title":"Who the building holds","narrative_seed":"Riley and Owen document ordinary resident routines rather than producing a sentimental campaign."},{"title":"The co-op number","narrative_seed":"Mateo finds a viable but difficult worker-cooperative financing path that requires residents to decide who is actually staying."},{"title":"After the set","narrative_seed":"A Drift benefit night ends with private choices about commitment, departure, and whether one more winter is a plan or an avoidance strategy."}]},{"slug":"northvale-last-reel","title":"The Last Reel","category":"history","min_relationship_stage":"friend","lead_slugs":["sofia-reyes","marcus-chen","mara-ellison","june-nakashima"],"location_slugs":["rialto-mountain-cinema","snowglass-gallery","north-fork-coffee","miners-hall"],"premise":"A damaged film from the 1988 Sunrise Gondola opening reveals the uncredited labor and relationships that built NorthVale’s modern destination image.","chapters":[{"title":"A reel without a label","narrative_seed":"Sofia finds a deteriorating film can behind a sealed projection-room panel at the Rialto."},{"title":"Faces in the frame","narrative_seed":"Marcus restores stills and recognizes workers whose names never appeared in the opening-day program."},{"title":"The community note","narrative_seed":"Mara connects one person in the film to the community note that later saved North Fork Coffee and possibly funded early worker housing."},{"title":"Who gets the credit","narrative_seed":"June helps build a public screening and archive record that credits labor without inventing a cleaner story than the evidence supports."}]},{"slug":"northvale-second-descent","title":"Second Descent","category":"personal","min_relationship_stage":"friend","lead_slugs":["mika-tanaka","sana-rahman","nico-alvarez","leila-haddad","elena-petrova"],"location_slugs":["halo-terrain-park","aurora-spa","northvale-community-clinic","bluebird-trailhead"],"premise":"Mika’s return from injury becomes a story about identity, consent, work pressure, and choosing what a successful comeback actually means.","chapters":[{"title":"The first easy lap","narrative_seed":"Mika asks for company on a deliberately unimpressive return lap and jokes too hard about how little it matters."},{"title":"The clip online","narrative_seed":"Nico discovers somebody posted the lap as comeback content, turning a private benchmark into public expectation."},{"title":"A different progression","narrative_seed":"Sana, Leila, and Elena help Mika separate medical readiness, performance readiness, and personal desire."},{"title":"The descent she chooses","narrative_seed":"At Bluebird Trailhead, Mika chooses a next step that may be competitive, recreational, or a pause—without the story treating any choice as failure."}]},{"slug":"northvale-broken-cable","title":"The Broken Cable","category":"infrastructure","min_relationship_stage":"acquaintance","lead_slugs":["mila-novak","andre-baptiste","signe-dahl","caleb-morgan","cassidy-reed"],"location_slugs":["sunrise-gondola","snowcat-garage","ski-patrol-headquarters","crows-nest-lodge"],"premise":"A retired cable sample fails differently than its maintenance record predicts, raising hard questions about an aging gondola without turning ordinary deferred maintenance into a cartoon conspiracy.","chapters":[{"title":"The fracture","narrative_seed":"Mila shows Signe a discarded cable section whose wear pattern does not match the logged reason for removal."},{"title":"What the record meant","narrative_seed":"Andre explains how inspection shorthand, parts availability, and pressure to avoid downtime can produce records that are technically true and operationally incomplete."},{"title":"The storm sequence","narrative_seed":"Caleb and Cassidy connect the wear to a past storm response and a temporary repair that was safe then but poorly documented later."},{"title":"Closing before failure","narrative_seed":"The group builds a defensible replacement and downtime recommendation, accepting public anger rather than waiting for certainty the mountain cannot provide."}]},{"slug":"northvale-cabin-mile-nine","title":"The Cabin at Mile Nine","category":"discovery","min_relationship_stage":"acquaintance","lead_slugs":["tessa-ward","nadine-baptiste","evan-cho","june-nakashima"],"location_slugs":["vale-and-pine-books","pine-lake-cabins","frostline-boathouse","bluebird-trailhead"],"premise":"Letters hidden in a withdrawn library book lead to a closed Pine Lake cabin that once housed teachers, nurses, and seasonal women with nowhere safe to stay.","chapters":[{"title":"The checkout card","narrative_seed":"Tessa finds repeated handwritten directions on the checkout card of a book nobody has borrowed in years."},{"title":"Mile nine","narrative_seed":"Nadine and Evan identify the directions as an old winter route to a cabin omitted from current guest maps."},{"title":"The women who stayed","narrative_seed":"June authenticates letters showing the cabin functioned as mutual aid rather than a romantic hideaway."},{"title":"A useful future","narrative_seed":"The group considers preserving the cabin as a small resident retreat, archive, or emergency refuge without turning private histories into a tourist attraction."}]}]$northvale_stories$::jsonb);
insert into public.together_story_arc_templates(
  slug,title,category,eligible_template_ids,min_relationship_stage,prerequisites,chapters,
  cooldown_days,repeatable,priority,active,world_scope,specific_world_id
)
select item->>'slug',item->>'title',item->>'category',
  array(select template.id from public.together_character_templates template
    where template.slug=any(array(select jsonb_array_elements_text(item->'lead_slugs')))),
  item->>'min_relationship_stage',
  jsonb_build_object('worldSlug','northvale','characterSlugs',item->'lead_slugs','locationSlugs',item->'location_slugs',
    'dialogueDriven',true,'requiresCorrectPlaceWhenAdvancing',true,'premise',item->>'premise'),
  (select jsonb_agg(jsonb_build_object('id','chapter-'||ordinality,'title',chapter->>'title',
    'userVisibility',case when ordinality=1 then 'contextual' else 'visible' end,'mayTriggerProactiveMessage',true,
    'mayCreateMoment',ordinality=jsonb_array_length(item->'chapters'),'narrativeSeed',chapter->>'narrative_seed',
    'minimumHoursBeforeNext',case when ordinality=1 then 12 else 24 end,
    'eligibleCharacterSlugs',item->'lead_slugs','eligibleLocationSlugs',item->'location_slugs') order by ordinality)
    from jsonb_array_elements(item->'chapters') with ordinality chapter_rows(chapter,ordinality)),
  90,false,'major',true,'specific','10000000-0000-4000-8000-000000000011'::uuid
from northvale_story_payload cross join lateral jsonb_array_elements(data) item
on conflict(slug) do update set title=excluded.title,category=excluded.category,
  eligible_template_ids=excluded.eligible_template_ids,min_relationship_stage=excluded.min_relationship_stage,
  prerequisites=excluded.prerequisites,chapters=excluded.chapters,world_scope='specific',
  specific_world_id=excluded.specific_world_id,active=true,updated_at=now();

create temporary table northvale_fact_payload(data jsonb) on commit drop;
insert into northvale_fact_payload values($northvale_facts$[{"slug":"northvale-ancestral-homeland","category":"history","title":"The valley before NorthVale","fact":"The North Fork valley lies within the ancestral homelands of the Nuche, or Ute peoples; modern acknowledgements do not substitute for consultation or authority.","location_slug":"miners-hall","trigger_terms":["Ute history","before the town","ancestral land"]},{"slug":"northvale-founded-1884","category":"history","title":"The silver camp","fact":"North Vale became a permanent silver settlement in 1884 and survived the mining collapse by remaining a service, rail, and family town.","location_slug":"argent-mine","trigger_terms":["founding","silver camp","1884"]},{"slug":"northvale-white-sunday","category":"history","title":"White Sunday","fact":"The avalanche of February 18, 1912 killed forty-one people and established NorthVale's enduring culture of shared mountain responsibility.","location_slug":"miners-hall","trigger_terms":["White Sunday","1912 avalanche","rescue history"]},{"slug":"northvale-rope-tow","category":"history","title":"The first rope tow","fact":"Residents built NorthVale's first community rope tow in 1947; the modern resort grew from that cooperative hill.","location_slug":"gondola-commons","trigger_terms":["rope tow","first ski hill","1947"]},{"slug":"northvale-vale-accord","category":"law","title":"The Vale Accord","fact":"The 1978 Vale Accord ties resort expansion to public access, watershed monitoring, rescue funding, community passes, and worker housing contributions.","location_slug":"miners-hall","trigger_terms":["Vale Accord","resort agreement","worker housing"]},{"slug":"northvale-accord-renewal","category":"current","title":"The 2026 renewal window","fact":"The Vale Accord's fifty-year renewal window opened in 2026, forcing the town and resort to renegotiate what mutual obligation means now.","location_slug":"miners-hall","trigger_terms":["Accord renewal","2026","renegotiation"]},{"slug":"northvale-population-swing","category":"economy","title":"Seasonal population","fact":"NorthVale grows from roughly 11,800 year-round residents to around 34,000 people during peak winter weeks.","location_slug":"lantern-square","trigger_terms":["population","peak season","crowds"]},{"slug":"northvale-juniper-house","category":"housing","title":"Juniper House","fact":"Juniper House is the largest seasonal-worker residence and may be sold after the current season, threatening a major piece of NorthVale's social infrastructure.","location_slug":"juniper-house","trigger_terms":["Juniper House","employee housing","lease"]},{"slug":"northvale-sunrise-age","category":"infrastructure","title":"The aging gondola","fact":"Sunrise Gondola opened in 1988 and now requires replacement planning, intensive maintenance, and uncomfortable decisions about downtime and expansion.","location_slug":"sunrise-gondola","trigger_terms":["Sunrise Gondola","cable","replacement"]},{"slug":"northvale-silver-basin-watershed","category":"environment","title":"The basin supplies the valley","fact":"Silver Basin feeds the North Fork watershed, making access, construction, sanitation, and road decisions relevant far beyond recreation.","location_slug":"silver-basin","trigger_terms":["watershed","Silver Basin","water supply"]},{"slug":"northvale-closure-etiquette","category":"etiquette","title":"Closures are not suggestions","fact":"Ignoring a closure transfers personal risk to patrollers, rescuers, guides, and families; locals treat that as a social failure, not merely a rule violation.","location_slug":"gate-seven","trigger_terms":["closure","rope ducking","backcountry gate"]},{"slug":"northvale-first-chair-bell","category":"tradition","title":"The first-chair bell","fact":"On major opening mornings, patrol rings a small brass bell at Gondola Commons only after the mountain is cleared for public access.","location_slug":"gondola-commons","trigger_terms":["first chair bell","opening morning","patrol bell"]},{"slug":"northvale-mud-season","category":"culture","title":"Mud season","fact":"Spring shoulder season closes businesses, empties streets, exposes friendships, and decides which seasonal residents are becoming locals.","location_slug":"old-vale","trigger_terms":["mud season","spring closure","after winter"]},{"slug":"northvale-summer-life","category":"culture","title":"The town after snow","fact":"Summer replaces skiing with biking, climbing, horses, lake days, construction, trail work, weddings, and long evenings rather than ending the world.","location_slug":"pine-lake","trigger_terms":["summer","off season","mountain biking"]},{"slug":"northvale-bluebird","category":"weather","title":"Bluebird does not mean harmless","fact":"Clear cold weather can follow heavy loading, poor visibility, and intense control work; beautiful conditions do not erase mountain risk.","location_slug":"avalanche-forecast-center","trigger_terms":["bluebird day","clear weather","snow stability"]},{"slug":"northvale-service-culture","category":"culture","title":"The town beneath the resort","fact":"Hospitality, maintenance, cleaning, transport, food, instruction, and rescue labor shape NorthVale as much as the visitors photographed on the mountain.","location_slug":"summit-village","trigger_terms":["service workers","resort staff","real town"]},{"slug":"northvale-community-passes","category":"economy","title":"Community access","fact":"Resident and worker pass programs are a Vale Accord obligation, not a charitable resort perk.","location_slug":"basecamp-outfitters","trigger_terms":["community pass","worker pass","access"]},{"slug":"northvale-storm-holds","category":"weather","title":"Storm holds rearrange the town","fact":"Wind, road closures, and lift holds routinely change work, dates, travel, lodging, and who ends up sharing a room for an hour.","location_slug":"alpine-room","trigger_terms":["storm hold","wind hold","road closure"]},{"slug":"northvale-safe-ride","category":"etiquette","title":"Nobody is abandoned after close","fact":"Bars, music venues, and worker circles maintain informal safe-ride habits because winter roads and late shifts make careless independence dangerous.","location_slug":"the-avalanche","trigger_terms":["safe ride","after close","driving in snow"]},{"slug":"northvale-private-homes","category":"etiquette","title":"Private access stays private","fact":"Employee rooms, cabins, homes, and staff spaces require invitation or established co-presence; familiarity with a character never implies entry.","location_slug":"juniper-house","trigger_terms":["come over","room","private cabin"]}]$northvale_facts$::jsonb);
insert into public.together_world_facts(
  world_id,slug,title,fact_text,category,truth_mode,knowledge_scope,content_level,location_id,
  topic_tags,trigger_terms,weight,cooldown_turns,active,metadata
)
select '10000000-0000-4000-8000-000000000011'::uuid,item->>'slug',item->>'title',item->>'fact',
  case item->>'category'
    when 'housing' then 'economy' when 'current' then 'local_knowledge' when 'environment' then 'local_knowledge'
    when 'etiquette' then 'custom' when 'infrastructure' then 'institution' when 'tradition' then 'culture'
    when 'weather' then 'local_knowledge' else item->>'category' end,
  'canonical','public','standard',location.id,
  array[item->>'category',item->>'location_slug'],array(select jsonb_array_elements_text(item->'trigger_terms')),
  1,24,true,jsonb_build_object('source','northvale_content_pack_v1','originalCategory',item->>'category')
from northvale_fact_payload cross join lateral jsonb_array_elements(data) item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000011'::uuid and location.slug=item->>'location_slug'
on conflict(world_id,slug) do update set title=excluded.title,fact_text=excluded.fact_text,category=excluded.category,
  truth_mode=excluded.truth_mode,knowledge_scope=excluded.knowledge_scope,content_level=excluded.content_level,
  location_id=excluded.location_id,topic_tags=excluded.topic_tags,trigger_terms=excluded.trigger_terms,
  weight=excluded.weight,cooldown_turns=excluded.cooldown_turns,active=true,metadata=excluded.metadata,updated_at=now();

create temporary table northvale_opportunity_payload(data jsonb) on commit drop;
insert into northvale_opportunity_payload values($northvale_opportunities$[{"slug":"northvale-why-stay","topic":"Why people stay past one season","angle":"Let a character separate the public reason they give from the private person, routine, or fear actually shaping the decision.","location_slugs":["north-fork-coffee","juniper-house","lakehouse-cafe"],"trigger_terms":["staying","one more winter","leave town"]},{"slug":"northvale-risk-language","topic":"Competence versus bravado","angle":"A mountain professional can explain that serious skill often looks quieter, slower, and less performative than confidence theater.","location_slugs":["ski-patrol-headquarters","high-country-guides","gate-seven"],"trigger_terms":["dangerous","expert","brave"]},{"slug":"northvale-housing","topic":"Seasonal housing pressure","angle":"Discuss the practical and emotional role of Juniper House without reducing residents to a policy statistic.","location_slugs":["juniper-house","miners-hall"],"trigger_terms":["rent","housing","Juniper House"]},{"slug":"northvale-accord","topic":"The Vale Accord renewal","angle":"Different characters should reveal different legitimate stakes: jobs, safety, water, access, housing, and financial survival.","location_slugs":["miners-hall","northvale-lodge","avalanche-forecast-center"],"trigger_terms":["Vale Accord","expansion","resort politics"]},{"slug":"northvale-white-sunday","topic":"White Sunday memory","angle":"Treat the disaster as labor, grief, and responsibility rather than romantic local legend.","location_slugs":["miners-hall","argent-mine","ski-patrol-headquarters"],"trigger_terms":["White Sunday","old avalanche","missing log"]},{"slug":"northvale-seasonal-love","topic":"Dating someone with a departure date","angle":"Explore whether temporary work makes affection less real, more honest, or easier to avoid defining.","location_slugs":["the-drift","the-avalanche","driftline-laundry"],"trigger_terms":["seasonal relationship","leaving in April","temporary"]},{"slug":"northvale-injury-identity","topic":"Who an athlete is while injured","angle":"Let recovery affect confidence, work, desire, and friendship without making injury the character's entire identity.","location_slugs":["community-clinic","aurora-spa","halo-terrain-park"],"trigger_terms":["injury","comeback","afraid to try"]},{"slug":"northvale-mud-season","topic":"The town with the audience gone","angle":"Characters can describe which businesses close, which friendships deepen, and why quiet is either relief or threat.","location_slugs":["old-vale","pine-lake","switchback-tavern"],"trigger_terms":["mud season","off season","quiet town"]},{"slug":"northvale-worker-visitor","topic":"Service intimacy and professional boundaries","angle":"Hospitality characters distinguish genuine interest from the warmth their job requires and name when the role has changed.","location_slugs":["northvale-lodge","alpine-room","emberline-kitchen"],"trigger_terms":["flirting at work","guest","professional"]},{"slug":"northvale-silver-basin","topic":"What controlled access would change","angle":"Balance recreation, water, jobs, wildlife, rescue burden, and the meaning of public terrain.","location_slugs":["silver-basin","high-country-guides","miners-hall"],"trigger_terms":["Silver Basin line","new terrain","watershed"]},{"slug":"northvale-family-expectation","topic":"Local families without dynasties","angle":"Explore ordinary inherited obligations—business shifts, caregiving, reputation, housing—not empire politics.","location_slugs":["old-vale","pine-lake","last-light-roadhouse"],"trigger_terms":["local family","grew up here","everyone knows"]},{"slug":"northvale-consent-weather","topic":"Weather-forced proximity","angle":"A storm may create time together, but never assumes romance, entry, touch, or an overnight invitation.","location_slugs":["alpine-room","crows-nest-lodge","driftline-laundry"],"trigger_terms":["stranded","storm night","stay here"]}]$northvale_opportunities$::jsonb);
insert into public.together_dialogue_opportunities(
  world_id,slug,topic,angle,framing,location_id,topic_tags,trigger_terms,content_level,
  interaction_modes,weight,cooldown_turns,active,metadata
)
select '10000000-0000-4000-8000-000000000011'::uuid,item->>'slug',item->>'topic',item->>'angle',
  'Optional only. Let this companion''s established personality, work, boundaries, history, and relationship stance determine their view.',
  location.id,array[item->>'topic'],array(select jsonb_array_elements_text(item->'trigger_terms')),
  'standard',array['remote','co_present'],1,24,true,
  jsonb_build_object('source','northvale_content_pack_v1','eligibleLocationSlugs',item->'location_slugs')
from northvale_opportunity_payload cross join lateral jsonb_array_elements(data) item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000011'::uuid
  and location.slug=(select value #>> '{}' from jsonb_array_elements(item->'location_slugs') limit 1)
on conflict(world_id,slug) do update set topic=excluded.topic,angle=excluded.angle,framing=excluded.framing,
  location_id=excluded.location_id,topic_tags=excluded.topic_tags,trigger_terms=excluded.trigger_terms,
  content_level=excluded.content_level,interaction_modes=excluded.interaction_modes,weight=excluded.weight,
  cooldown_turns=excluded.cooldown_turns,active=true,metadata=excluded.metadata,updated_at=now();

create temporary table northvale_date_payload(data jsonb) on commit drop;
insert into northvale_date_payload values($northvale_dates$[{"slug":"northvale-first-tracks","title":"First Tracks Before Sunrise","location_slug":"midstation-lodge","season":"winter","tone":"active","setup":"Meet before public opening for breakfast, a cleared easy run, and the strange intimacy of a mountain still occupied mostly by workers."},{"slug":"northvale-storm-hold-drink","title":"A Storm-Hold Drink","location_slug":"alpine-room","season":"winter","tone":"intimate","setup":"A lift hold creates time for a drink and an honest conversation, with no assumption that forced proximity changes boundaries."},{"slug":"northvale-lantern-skate","title":"Lantern Skate at Pine Lake","location_slug":"pine-lake","season":"winter","tone":"romantic","setup":"Skate or walk the maintained loop, warm up at Lakehouse Cafe, and decide whether the sauna reservation should remain a future plan."},{"slug":"northvale-hot-springs-after-patrol","title":"Hot Springs After Patrol","location_slug":"silver-basin-hot-springs","season":"winter","tone":"sensual","setup":"A reserved recovery hour after a difficult workday makes room for care, quiet, and explicit choices about closeness."},{"slug":"northvale-late-laundry","title":"The Late Laundry Shift","location_slug":"driftline-laundry","season":"winter","tone":"playful","setup":"Share machines, vending-machine snacks, and the unglamorous facts of seasonal life while a storm builds outside."},{"slug":"northvale-rialto-revival","title":"Rialto Revival Night","location_slug":"rialto-mountain-cinema","season":"any","tone":"nostalgic","setup":"Choose a restored film, sit through the discussion afterward, and learn what kind of story each person believes deserves preserving."},{"slug":"northvale-bluebird-lunch","title":"Bluebird Lunch at Midstation","location_slug":"midstation-lodge","season":"winter","tone":"easy","setup":"Take a long lunch on a clear day while respecting that beautiful weather can follow exhausting control work."},{"slug":"northvale-bookshop-closing","title":"Bookshop at Closing Time","location_slug":"vale-and-pine-books","season":"any","tone":"quiet","setup":"Help close the store, trade one recommendation each, and continue the conversation only if the invitation is explicit."},{"slug":"northvale-stillwater-hour","title":"Stillwater Hour","location_slug":"stillwater-sauna-house","season":"winter","tone":"restorative","setup":"Move between a quiet sauna session, tea, and a lake view without treating wellness work as automatic intimacy."},{"slug":"northvale-summer-horse-trail","title":"Elk Meadow Evening Ride","location_slug":"elk-meadow-stables","season":"summer","tone":"active","setup":"Take a guided evening ride through wildflowers, then eat outside at Lakehouse Cafe."},{"slug":"northvale-mud-season-drive","title":"Mud-Season Road Trip","location_slug":"last-light-roadhouse","season":"mud_season","tone":"candid","setup":"Drive the empty valley road for lunch when half the town is closed and talk about whether staying feels different without an audience."},{"slug":"northvale-aspen-photo-walk","title":"Golden Aspen Photo Walk","location_slug":"bluebird-trailhead","season":"autumn","tone":"creative","setup":"Walk a short legal trail with a camera or sketchbook and let the town’s brief quiet season set the pace."},{"slug":"northvale-drift-backstage","title":"After the Last Song","location_slug":"the-drift","season":"any","tone":"electric","setup":"Help coil cables after a set, split late food, and distinguish stage chemistry from a private invitation."},{"slug":"northvale-switchback-supper","title":"Off-Menu Supper","location_slug":"switchback-tavern","season":"any","tone":"warm","setup":"Share a late staff meal after the public room clears, with professional access remaining separate from romantic access."},{"slug":"northvale-snowcat-sunset","title":"Authorized Snowcat Sunset","location_slug":"snowcat-garage","season":"winter","tone":"adventurous","setup":"Join an authorized operations ride during a scheduled transfer, watch the light change, and never turn restricted work terrain into casual access."},{"slug":"northvale-crows-nest-night","title":"A Night at Crow’s Nest","location_slug":"crows-nest-lodge","season":"winter","tone":"secluded","setup":"Reach the lodge through a properly planned route, share dinner, and let weather decide whether the return remains sensible."},{"slug":"northvale-snowglass-opening","title":"Snowglass Opening","location_slug":"snowglass-gallery","season":"any","tone":"social","setup":"Attend a small opening, choose the piece each person would actually live with, and escape the polished room for street food afterward."},{"slug":"northvale-summer-lake-day","title":"Pine Lake Summer Day","location_slug":"frostline-boathouse","season":"summer","tone":"playful","setup":"Rent a paddleboard, swim only in approved conditions, and end with towels, music, and a slow lunch."}]$northvale_dates$::jsonb);
insert into public.together_date_templates(
  id,name,slug,world_id,location_id,description,hero_asset_key,phases,unlock_rules,entitlement_key,active,metadata
)
select ('4f000000-0000-4000-8011-'||lpad(ordinality::text,12,'0'))::uuid,item->>'title',item->>'slug',
  '10000000-0000-4000-8000-000000000011'::uuid,location.id,item->>'setup','northvale-hero',
  jsonb_build_array(
    jsonb_build_object('id','arrival','title','Arrive','choices',jsonb_build_array(
      jsonb_build_object('id','lean-in','label','Lean into the plan'),jsonb_build_object('id','take-it-in','label','Take in the moment'))),
    jsonb_build_object('id','conversation','title','Settle in','choices',jsonb_build_array(
      jsonb_build_object('id','ask-real','label','Ask something real'),jsonb_build_object('id','follow-mood','label','Follow the mood'))),
    jsonb_build_object('id','turn','title','Something changes','choices',jsonb_build_array(
      jsonb_build_object('id','stay','label','Stay a little longer'),jsonb_build_object('id','change-pace','label','Change the pace'))),
    jsonb_build_object('id','resolution','title','What you keep','choices','[]'::jsonb)
  ),
  '{"familiarity":12,"trust":10,"allowed_stages":["acquaintance","friend","flirting","dating","exclusive","long_term"]}'::jsonb,
  'worlds.standard',true,jsonb_build_object('source','northvale_content_pack_v1','season',item->>'season','tone',item->>'tone')
from northvale_date_payload cross join lateral jsonb_array_elements(data) with ordinality payload(item,ordinality)
join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000011'::uuid and location.slug=item->>'location_slug'
on conflict(id) do update set name=excluded.name,slug=excluded.slug,world_id=excluded.world_id,
  location_id=excluded.location_id,description=excluded.description,hero_asset_key=excluded.hero_asset_key,
  phases=excluded.phases,unlock_rules=excluded.unlock_rules,entitlement_key=excluded.entitlement_key,
  active=true,metadata=excluded.metadata,updated_at=now();

update public.together_worlds set metadata=metadata||jsonb_build_object(
  'residentCompanionCount',45,'residentRosterStatus','ready','residentScheduleStatus','authored_weekly_v2',
  'socialGraphStatus','authored_v1','recurringEventCount',6,'storyArcCount',7,'worldFactCount',20,
  'dialogueOpportunityCount',12,'nativeDateCount',18,'residentPortraitStatus','primary_portraits_ready',
  'mappedResidentPortraitCount',45
),updated_at=now() where id='10000000-0000-4000-8000-000000000011'::uuid;

do $$
declare schedule_count int;incomplete_days int;invalid_locations int;edge_count int;event_count int;
  story_count int;fact_count int;opportunity_count int;date_count int;
begin
  select count(*) into schedule_count from public.together_schedule_templates where character_version_id::text like '25000000-0000-4000-8011-%';
  select count(*) into incomplete_days from(
    select version.id,day from public.together_character_versions version cross join generate_series(0,6) day
    left join public.together_schedule_templates schedule on schedule.character_version_id=version.id and schedule.day_of_week=day
    where version.id::text like '25000000-0000-4000-8011-%'
    group by version.id,day having count(schedule.id)<6
  ) incomplete;
  select count(*) into invalid_locations from public.together_schedule_templates schedule
    left join public.together_locations location on location.id=schedule.location_id
    where schedule.character_version_id::text like '25000000-0000-4000-8011-%'
      and schedule.location_id is not null and location.world_id is distinct from '10000000-0000-4000-8000-000000000011'::uuid;
  select count(*) into edge_count from public.together_character_relationship_edges where world_id='10000000-0000-4000-8000-000000000011'::uuid;
  select count(*) into event_count from public.together_event_templates where world_id='10000000-0000-4000-8000-000000000011'::uuid and active;
  select count(*) into story_count from public.together_story_arc_templates where specific_world_id='10000000-0000-4000-8000-000000000011'::uuid and active;
  select count(*) into fact_count from public.together_world_facts where world_id='10000000-0000-4000-8000-000000000011'::uuid and active;
  select count(*) into opportunity_count from public.together_dialogue_opportunities where world_id='10000000-0000-4000-8000-000000000011'::uuid and active;
  select count(*) into date_count from public.together_date_templates where world_id='10000000-0000-4000-8000-000000000011'::uuid and active;
  if schedule_count<>1890 or incomplete_days<>0 or invalid_locations<>0 or edge_count<82 or event_count<>6
    or story_count<>7 or fact_count<>20 or opportunity_count<>12 or date_count<>18 then
    raise exception 'NorthVale simulation validation failed: schedules %, incomplete %, invalid %, edges %, events %, stories %, facts %, opportunities %, dates %',
      schedule_count,incomplete_days,invalid_locations,edge_count,event_count,story_count,fact_count,opportunity_count,date_count;
  end if;
end $$;

commit;
